// ─────────────────────────────────────────────────────────────────────────
// FAN AUDIENCE GROWTH — connect real platform APIs here:
//   Spotify for Artists (SPOTIFY_CLIENT_ID/SECRET), YouTube Data API
//   (YOUTUBE_API_KEY), Instagram Graph API (INSTAGRAM_ACCESS_TOKEN),
//   TikTok Content Posting API (TIKTOK_ACCESS_TOKEN) — all already defined
//   in backend/.env.example. Until connected this reports 'partial' with
//   the missing credentials — it does not fabricate follower/growth numbers.
// ─────────────────────────────────────────────────────────────────────────
const input = $input.first().json;
const missing = [];
if (!$env.SPOTIFY_CLIENT_ID || !$env.SPOTIFY_CLIENT_SECRET) missing.push('SPOTIFY_CLIENT_ID', 'SPOTIFY_CLIENT_SECRET');
if (!$env.YOUTUBE_API_KEY) missing.push('YOUTUBE_API_KEY');
if (!$env.INSTAGRAM_ACCESS_TOKEN) missing.push('INSTAGRAM_ACCESS_TOKEN');
if (!$env.TIKTOK_ACCESS_TOKEN) missing.push('TIKTOK_ACCESS_TOKEN');

return [{ json: {
  mission_id: input.mission_id,
  execution_id: input.execution_id,
  status: missing.length ? 'partial' : 'completed',
  summary: missing.length ? `Fan Intelligence ready — waiting on: ${missing.join(', ')}` : 'Fan growth analysis complete',
  results: {
    audience_growth: null,
    top_countries: null,
    top_cities: null,
    follower_velocity: null,
    fan_overlap: null,
    growth_prediction: null,
    missing_credentials: missing,
  },
} }];
